insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',1,'Língua Portuguesa',null,'A frase a seguir refere-se à simbologia cultural dos animais, atribuindo à abelha a imagem do trabalho. “A abelha vive fazendo cera. Sempre. E com tudo isso, como é que a abelha consegue ser a imagem do labor incessante?” (Eno T. Wanke) Em todas as frases abaixo há alusões implícitas a essa simbologia dos animais. Assinale a frase que mostra adequadamente o valor simbólico do animal presente na frase.','{"A": "“Raposa velha não cai no laço.” / esperteza.", "B": "“A mais nobre conquista que o homem tenha jamais feito, é a desse cavalo altivo e fogoso, que partilha com ele as fadigas da guerra e a glória dos combates.” / lealdade.", "C": "“O elefante deixa-se acariciar. O piolho, não.” / gentileza.", "D": "“A tartaruga leva um dia imenso em seu puro passeio solitário.” / paciência.", "E": "“A lebre dorme de olhos abertos.” / inteligência."}'::jsonb,'A',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',2,'Língua Portuguesa',null,'Em todas as opções abaixo as frases foram reescritas de modo a eliminar o advérbio não, mas mantendo-se o sentido original. Assinale a frase em que essa modificação foi feita de forma adequada.','{"A": "“A abelha atarefada não tem tempo para tristeza” (Eno T. Wanke) / a abelha atarefada dispensa o tempo de tristeza.", "B": "“Perdoamos frequentemente aos que nos aborrecem, mas não podemos perdoar aos que nós aborrecemos.”(La Rochefoucaud) / Perdoamos frequentemente aos que nos aborrecem, mas é proibido perdoar aos que nós aborrecemos.", "C": "“Se a Academia não tem autoridade acadêmica, então os satíricos e os engraçados também não têm graça nenhuma.” (João Ribeiro) / Se a Academia precisa de autoridade acadêmica, então os satíricos e os engraçados também não têm graça nenhuma.", "D": "“De todas as taras sexuais, não existe nenhuma mais estranha do que a abstinência.” (Millôr Fernandes) / De todas as taras sexuais, há uma mais estranha do que a abstinência.", "E": "“Um dia desses eles declaram que tudo não passou de cinquenta anos de brincadeira.” (Millôr Fernandes) / Um dia desses eles declaram que tudo se limitou a cinquenta anos de brincadeira."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',3,'Língua Portuguesa',null,'As opções a seguir apresentam frases que trazem marcas de subjetividade, à exceção de uma. Assinale-a.','{"A": "“As sociedades modernas parecem-me orgulhar-se demais da abolição da escravatura” (Marquês de Custine).", "B": "“Meu desejo sincero seria que nossa Academia Brasileira não se esquecesse tanto de que é também de ... Letras” (Mário de Andrade).", "C": "“Meu filho, Absalão! meu filho, Absalão! Quem me dera que eu morrera por ti!” (Velho Testamento).", "D": "“Um tolo encontra sempre outro mais tolo que o admira” (Boileau).", "E": "“Felizmente, o meu povo brasileiro detesta andar. Só anda a pé por prescrição médica” (Paulo Mendes Campos)."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',4,'Língua Portuguesa',null,'Assinale a opção que apresenta a frase cuja palavra sublinhada só tem uma grafia possível.','{"A": "“Aborígines são gente de valor escasso que atravanca o solo de um país recém-descoberto” (Ambrose Bierce).", "B": "“Sem pontos de parada, / solto nas ruas como um táxi, / sem o esperar, querer, / sem ter por quê, se toma o enfarte” (João Cabral de Melo Neto).", "C": "“Os bêbados têm ligações profundas com a verdade.” (anônimo).", "D": "“A cozinha brasileira é de extremos: ou os pratos carregadíssimos, ou então a vulgaridade.” (Ribeiro Couto),", "E": "“Tudo o que vejo lá fora respira vida, a cabra que rumina ao pé de uma carroça, a galinha que marisca no chão da rua, o trem da Estrada Central que bufa, assobia, fumega e passa, a palmeira que investe para o céu...” (Machado de Assis – Dom Casmurro)."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',5,'Língua Portuguesa',null,'Assinale a opção que indica a frase em que ocorreu a substituição adequada da locução adverbial sublinhada por um advérbio semanticamente equivalente.','{"A": "“Capistrano de Abreu declarava só ter entrado para a sociedade humana porque não foi consultado com antecedência” (Capistrano de Abreu) / anteriormente.", "B": "“Os abusos, como os dentes, nunca se arrancam sem dores” (Marquês de Maricá) / impunemente.", "C": "“E se Adão não tivesse resistido àquela operação nas costelas a que se submeteu antes do momento adequado” (Eno T. Wanke) / prematuramente.", "D": "“Os acontecimentos tinham ampliado sua inteligência por natureza estreita” (Anatole France) / originalmente.", "E": "“Se o mundo fosse, de fato, governado pelo acaso, não haveria tantas injustiças” (Galiani) / claramente."}'::jsonb,'C',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',6,'Língua Portuguesa',null,'Assinale a frase em que ocorreu a troca indevida entre sob e sobre.','{"A": "“Odeio as combinações hipócritas do absolutismo dissimulado sob as formas democráticas ou republicanas” (Rui Barbosa).", "B": "“A história, na verdade, é pouco mais que um registro de crimes sobre as loucuras e as desgraças da humanidade” (Gibbon).", "C": "“Escreve as ofensas na areia e os benefícios sob o mármore” (Benjamin Franklin).", "D": "“A metafísica está no ar. Não podemos deixá-la senão deixá- la ali, pois estamos sob ela” (Clemenceau).", "E": "“Não há uma ideia nascida de um espírito humano que não tenha feito correr sangue sobre a terra” (Charles Maurras)."}'::jsonb,'C',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',7,'Língua Portuguesa',null,'Em todas as opções abaixo há uma metáfora ou uma comparação; assinale a opção em que a razão da comparação metafórica está inadequadamente indicada.','{"A": "“O absurdo é o sal da vida” (Ledo Ivo) / o que dá prazer.", "B": "“A gasolina é o incenso da civilização” (Ramon de la Serna) / o que cria industrialização.", "C": "“São Paulo é uma locomotiva poderosa, puxando 25 vagões” (Artur Neiva) / força desenvolvimentista.", "D": "“Para mim, a vida é a miniatura do teatro” (Procópio Ferreira) / representação falsa.", "E": "“O tempo é um rio formado pelos eventos, uma torrente impetuosa” (Marco Aurélio) / sucessão inédita de acontecimentos."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',8,'Língua Portuguesa',null,'Assinale a frase em que a substituição da locução sublinhada por um adjetivo é feita de forma adequada.','{"A": "“A saudade é a memória do coração” (Coelho Neto) / cardíaca.", "B": "“O casamento é como a pessoa que quer tomar um copo de leite e compra uma vaca” (Max Nunes) / lácteo.", "C": "“Um sintoma de liberdade é o som de uma gargalhada” (anônimo) / livre.", "D": "“Lembre-se de que o segredo da felicidade está na liberdade” (Tucídides) / feliz.", "E": "“O riso é o sol que afugenta o inverno do rosto do homem” Victor Hugo) / humano."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',9,'Língua Portuguesa',null,'Assinale a frase que mostra uma inadequação semântica entre as palavras sublinhadas.','{"A": "Hoje há remédios para todas as doenças.", "B": "A empresa encontra soluções para todos os problemas.", "C": "Nem sempre há boas sentenças em todos os julgamentos.", "D": "A vida nem sempre dá satisfação a todos os desejos.", "E": "Os otimistas encontram saída para todas as dúvidas."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',10,'Língua Portuguesa',null,'Assinale a frase adequadamente composta, respeitando os valores semânticos das palavras empregadas.','{"A": "Abruptamente, o menino entreabriu a porta do escritório.", "B": "Pelo orifício da câmara, penetrou uma faixa de luz.", "C": "Os destroços da parede desabada atrapalhavam a passagem.", "D": "O lutador, apesar de forte, mostrava medo do adversário.", "E": "As frutas caídas deslizavam pela escada abaixo."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',11,'Língua Portuguesa',null,'Assinale a frase em que a grafia da palavra sublinhada está correta.','{"A": "“A razão porque pessoas culpam as gerações anteriores é que há apenas uma outra escolha.”", "B": "“Pais se perguntam por que os rios são amargos, quando eles mesmos envenenaram a fonte.”", "C": "“Não há nenhum dever na arte por que a arte é livre.”", "D": "“A dança deve sua existência à música, porquê?”", "E": "“Eu sei que a poesia é indispensável, mas não sei por que.”"}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',12,'Língua Portuguesa',null,'Todas as opções abaixo mostram formas de diminutivos dos vocábulos entre parênteses, com o sufixo –inho. Assinale a opção em que todas as formas estão corretamente grafadas.','{"A": "paizinho (pai) / paisinho (país) / raizinha (raiz).", "B": "papelsinho (papel) / piresinho (pires) / reizinho (rei).", "C": "tunelzinho (túnel) / lapizinho (lápis) / avozinho (avô).", "D": "adeusinho (adeus) / camizinha (camisa) / mãozinha (mão).", "E": "dorzinha (dor) / tecnicazinha (técnica) / xadresinho (xadrez)."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',13,'Língua Portuguesa',null,'Assinale a frase que mostra a palavra mais numa classe gramatical diferente das demais.','{"A": "“Os funcionários são como os livros de bibliotecas: os que estão em lugares mais altos são os que menos prestam” (Paul Masson).", "B": "“Mais vale um galo no terreiro do que dois na testa” (Barão de Itararé).", "C": "“A mulher chega à maturidade quando seus sapatos começam a incomodá-la mais do que os homens” (Aldo Cammarota).", "D": "“Um homem parado é a coisa mais horrível que pode haver. Mulher não aguenta o marido em casa o dia inteiro” (Girsz Aronson).", "E": "“Para evitar o estresse, evite excitação; passe mais tempo com a sua esposa” (Robert Olsen)."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',14,'Literatura',null,'Assinale a opção que apresenta a frase que se refere ao romance Dom Casmurro, de Machado de Assis.','{"A": "Narrativa em primeira pessoa, na qual o narrador recorda sua vida passada.", "B": "Narrativa de aventuras, na qual o narrador se lembra de uma série de aventuras amorosas.", "C": "Narrativa amorosa, de caráter romântico, na qual o narrador presta homenagens à sua musa.", "D": "Narrativa de memórias, em terceira pessoa, na qual o narrador faz uma seleção de fatos históricos.", "E": "Narrativa histórica, na qual estão expostos os fatos mais importantes de nosso período monárquico."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',15,'Literatura',null,'Assinale a opção que apresenta, respectivamente, um autor da literatura portuguesa e outro da literatura brasileira, que pertencem ao mesmo movimento literário.','{"A": "Camões / José de Alencar.", "B": "Eça de Queiroz / Machado de Assis.", "C": "Alexandre Herculano / Aluísio Azevedo.", "D": "Júlio Dinis / Lima Barreto.", "E": "Camilo Castelo Branco / Guimarães Rosa."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',16,'Matemática',null,'João recebeu certa quantia. Com a terça parte da quantia, pagou os gastos com o cartão de crédito, e pagou o aluguel com a quinta parte do restante. Da quantia recebida, a fração que representa a parte que João ainda tem disponível é','{"A": "2 5", "B": "3 5", "C": "7 15", "D": "8 15", "E": ""}'::jsonb,'D',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',17,'Matemática',null,'30 17 Em certa pista, um carro de corrida, mantendo velocidade média de 100 km/h durante 2 horas deu exatamente 45 voltas. Na mesma pista, aumentando a velocidade média para 180 km/h, o número de voltas que serão dadas nas mesmas 2 horas é','{"A": "25.", "B": "30.", "C": "36.", "D": "72.", "E": "81."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',18,'Matemática',null,'Considere a sequência aritmética: 53, 60, 67, 74, ... O primeiro termo dessa sequência a ultrapassar 1000 é','{"A": "1001.", "B": "1002.", "C": "1003.", "D": "1004.", "E": "1005."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',19,'Matemática',null,'Em uma lista de 5 números naturais, 𝑥 é o menor. Dessa lista, sabe-se que a moda (única) é 24, a mediana é 21 e a média é 20. O menor valor que 𝑥 pode assumir é','{"A": "9.", "B": "10.", "C": "11.", "D": "12.", "E": "13."}'::jsonb,'C',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',20,'Matemática',null,'O ponto P do plano cartesiano possui coordenadas iguais e é equidistante dos pontos (1, 4) e (7, 0). O ponto P é','{"A": "(8, 8).", "B": "(9, 9).", "C": "(10, 10).", "D": "(11, 11).", "E": "(12, 12)."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',21,'Matemática',null,'Em um pátio, 240 soldados deverão ser dispostos em formação retangular de linhas e colunas. Por exemplo, a figura abaixo mostra 12 soldados em uma formação retangular de 3 linhas e 4 colunas. Para os 240 soldados, a formação deve ter ao menos, 4 linhas e ao menos 4 colunas. Assinale a opção que indica o número de maneiras diferentes de realizar essa formação.','{"A": "7.", "B": "8.", "C": "12.", "D": "14.", "E": "18."}'::jsonb,'D',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',22,'Matemática',null,'Para conseguir ingresso em um curso de especialização, cada candidato deve resolver uma prova de 25 questões cuja pontuação é feita da seguinte forma: • 5 pontos por cada resposta correta. • −2 pontos por cada resposta errada. Hugo fez a prova e obteve 69 pontos. Assinale a opção que indica o número de questões que Hugo acertou.','{"A": "16.", "B": "17.", "C": "18.", "D": "19.", "E": "20."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',23,'Matemática',null,'Max e Rubens estão andando de bicicleta em uma pista circular. Eles andam em sentidos opostos. Max dá uma volta na pista a cada 6 minutos e Rubens dá uma volta na pista a cada 10 minutos. Em um determinado momento eles se cruzam em um ponto P da pista. Eles voltarão a se cruzar pela primeira vez nesse mesmo ponto P após','{"A": "6 minutos.", "B": "10 minutos.", "C": "24 minutos.", "D": "30 minutos.", "E": "60 minutos."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',24,'Matemática',null,'Joana comprou uma bota que custava R$ 250,00 à vista e pagou em duas parcelas iguais de R$ 150,00 cada uma, sendo a primeira parcela paga no ato da compra e a segunda, um mês após. A taxa de juros mensal que Joana pagou nessa compra foi de','{"A": "10%.", "B": "20%.", "C": "25%.", "D": "30%.", "E": "50%."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',25,'Matemática',null,'Considere a desigualdade |3𝑥−2| < 10. O número de valores inteiros de 𝑥 que satisfazem a desigualdade dada é','{"A": "4.", "B": "5.", "C": "6.", "D": "7.", "E": "8."}'::jsonb,'C',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',26,'Matemática',null,'Os elementos de cada linha e de cada coluna da matriz 5 x 5 a seguir formam progressões geométricas. [ 2 24 12 𝑁 9 ] O valor de 𝑁 é','{"A": "6.", "B": "6√2.", "C": "6√3.", "D": "2√6.", "E": "3√6."}'::jsonb,'B',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',27,'Matemática',null,'Considere a equação 2𝑥3 −𝑚𝑥2 + 4𝑥−3 = 0, onde 𝑚 é um número real. Sabe-se que 𝑥= −1 é raiz dessa equação. A soma das 3 raízes da equação dada é','{"A": "−3.", "B": "−1.", "C": "−9 2 .", "D": "9 2 .", "E": "9."}'::jsonb,'C',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',28,'Matemática',null,'A quantidade de números de 4 algarismos diferentes que são maiores do que 3000 e menores do que 9000 é','{"A": "6004.", "B": "4084.", "C": "3024.", "D": "2094.", "E": "2064."}'::jsonb,'C',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',29,'Matemática',null,'Em um sistema de coordenadas cartesianas xy, considere as retas de equações 2𝑥−𝑦+ 1 = 0 e 𝑥+ 𝑦−4 = 0. A área do triângulo delimitado por essas duas retas e pelo eixo-x é','{"A": "19 3 .", "B": "21 5 .", "C": "23 4 .", "D": "25 3 .", "E": "27 4 ."}'::jsonb,'E',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',30,'Matemática',null,'Solange e Marcelo fazem parte de um grupo de 10 pessoas. Sorteiam-se duas pessoas desse grupo, em sequência e sem reposição. A probabilidade de Solange ser sorteada e Marcelo não ser sorteado é de','{"A": "8 45.", "B": "1 10.", "C": "1 5.", "D": "4 25.", "E": "3 40."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',31,'Física',null,'Uma partícula é uniformemente retardada percorrendo, até parar, 80m em 4s. Durante o último segundo de movimento a partícula percorreu','{"A": "5m.", "B": "10m.", "C": "12m.", "D": "16m.", "E": "20m."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',32,'Física',null,'A figura a seguir mostra uma esfera maciça de centro C na qual há uma mosca em repouso pousada na posição indicada. Nela estão desenhados cinco segmentos orientados. Assinale a opção que indica o segmento que representa a força exercida pela esfera sobre a mosca.','{"A": "I.", "B": "II.", "C": "III.", "D": "IV.", "E": "V."}'::jsonb,'C',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',33,'Física',null,'O gráfico representa a relação entre a temperatura medida em uma escala de temperatura hipotética X e a temperatura medida na escala Celsius, sob pressão normal. A temperatura de fusão do gelo e a de ebulição da água são, em graus X, respectivamente iguais a','{"A": "-20 e 50.", "B": "20 e 50.", "C": "-20 e 55.", "D": "20 e 55.", "E": "-20 e 60."}'::jsonb,'C',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',34,'Física',null,'Analise as afirmativas a seguir. I. As moléculas de um corpo, quer ele se encontre na fase sólida, na fase líquida ou na fase gasosa, possuem energia cinética, mas não possuem calor. Calor é energia em trânsito. II. Quando a energia cinética de um corpo varia, a energia cinética média de suas moléculas também varia. Consequentemente, ele cedeu ou recebeu energia, mas não necessariamente calor. A energia pode ter sido por ele cedida ou recebida sob forma de trabalho. III. A fase em que uma substância se encontra depende de suas condições de pressão e temperatura, é possível que uma substância se encontre na fase sólida e líquida, por exemplo, em uma mesma temperatura. Está correto o que se afirma em','{"A": "II, apenas.", "B": "I e II, apenas.", "C": "I e III, apenas.", "D": "II e III, apenas.", "E": "I, II e III."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',35,'Física',null,'Dois balões positivamente carregados são utilizados para induzir cargas em bastões metálicos, alinhadas e em contato, que, inicialmente, estavam eletricamente neutros. Conforme mostrado na figura, os balões estão próximos, mas jamais chegam a tocar os bastões. Note e adote: o contato entre dois objetos metálicos permite a passagem de cargas elétricas entre um e outro. Suponha que o ar no entorno seja um isolante perfeito. Nessa configuração, os bastões 1, 2 e 3 terão, respectivamente, as seguintes cargas totais:','{"A": "1: negativo; 2: positivo; 3: negativo.", "B": "1: zero; 2: negativo; 3: zero.", "C": "1: zero; 2: negativo; 3: negativo.", "D": "1: negativo; 2: zero; 3: negativo.", "E": "1: zero; 2: zero; 3: zero."}'::jsonb,'A',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',36,'Física',null,'Um móvel (1), de pequenas dimensões, parte do repouso uniformemente acelerado à razão de 2 m/s2 no instante em que passa por ele outro móvel (2) animado por um movimento uniforme com uma velocidade de 10m/s. Suponha que o móvel (1) persiga o móvel (2) até alcançá-lo. Durante a perseguição, isto é, entre o instante em que o móvel (1) parte e o instante em que alcança o móvel (2), a maior distância entre eles foi de','{"A": "15m.", "B": "25m.", "C": "50m.", "D": "75m.", "E": "100m."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',37,'Física',null,'Um caixote de 100 kg sobe a rampa representada na figura ao longo da reta de maior declive com uma velocidade constante de módulo igual a 1,5 m/s, à custa da energia fornecida por um motor. O coeficiente de atrito cinético entre o bloco e a rampa é μ = 0,25. No local, g = 10 m/s2. Considere a roldana e os fios ideais; considere desprezíveis os atritos no eixo da roldana, o trecho do fio que prende o bloco à roldana paralelo à rampa e o trecho do fio que liga a roldana ao motor vertical. Nesse caso, o motor está desenvolvendo uma potência útil de','{"A": "0,80kW.", "B": "1,0kW.", "C": "1,2kW.", "D": "1,6kW.", "E": "3,2kW."}'::jsonb,'C',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',38,'Física',null,'Tem-se uma esfera metálica oca de raio R à temperatura ambiente. A interseção dessa esfera com um plano é um círculo. Em particular, quando o plano contém o centro C da esfera, o círculo obtido é um “círculo máximo”, de raio igual ao raio R da esfera, como ilustra a figura. Quando a temperatura sofre uma variação ∆θ, o volume da esfera sofre uma variação ∆V e a área do círculo máximo sofre variação ∆A. No entanto, seja qual for a variação de temperatura ocorrida, a razão ∆𝑉 ∆𝐴 permanece igual a','{"A": "2R.", "B": "3 4R.", "C": "R.", "D": "2 3R.", "E": "1 2R."}'::jsonb,'A',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',39,'Física',null,'Uma esfera de massa m, quando largada de um nível de potencial gravitacional A, pode chegar até o nível B de três maneiras diferentes: (I) cair livremente, (II) através de um pêndulo ou (III) por um plano inclinado. Se V(I), V(II) e V(III) são, respectivamente, as velocidades com que (I), (II) e (III) chegam em B, é correto afirmar que','{"A": "V(I) = V(II) = V(III).", "B": "V(I) > V(II) = V(III).", "C": "V(I) < V(II) = V(III).", "D": "V(I) > V(II) > V(III).", "E": "V(I) < V(II) < V(III)."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',40,'Física',null,'A figura a seguir representa, em um gráfico cartesiano, como a velocidade escalar de uma partícula em movimento varia em função do tempo. A velocidade escalar média dessa partícula entre os instantes t1 e t2 foi de','{"A": "27km/h.", "B": "32km/h.", "C": "42km/h.", "D": "57km/h.", "E": "62km/h."}'::jsonb,'C',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',41,'Física',null,'Um bloco de 4 kg se desloca em linha reta sobre uma superfície plana e horizontal, uniformemente retardado à razão de 7,5m/s2. Considere g = 10m/s2. O módulo da força que a superfície de apoio exerce sobre ele é igual a','{"A": "40N.", "B": "42N.", "C": "44N.", "D": "48N.", "E": "50N."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',42,'Física',null,'Uma partícula está se movendo com aceleração a⃗ horizontal, constante de módulo igual a 4 m/s2. Em um determinado instante, o vetor velocidade v⃗ da partícula, de módulo igual a 24 m/s, forma um ângulo de 120o com o vetor aceleração 𝑎 , como ilustra a figura. A contar desse instante, para que o vetor velocidade 𝑣 se torne perpendicular ao vetor aceleração 𝑎 , decorreram','{"A": "2s.", "B": "3s.", "C": "4s.", "D": "6s.", "E": "8s."}'::jsonb,'B',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',43,'Física',null,'O gráfico abaixo indica a variação de temperatura ΔT, em função da quantidade de calor Q, transferida a dois sistemas A e B, de massas iguais, inseridos em calorímetros ideais. De acordo com a análise gráfica é possível concluir que a relação entre o calor específico (cA) e (cB) dos materiais presentes nos sistemas A e B, respectivamente, é','{"A": "cA = 4.cB", "B": "cA = 2.cB", "C": "cA = cB", "D": "cA = cB 2", "E": "cA = cB 4"}'::jsonb,'D',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',44,'Física',null,'Um calorímetro de capacidade térmica desprezível contém 300g de gelo a 0oC. Nele são injetados 30g de vapor d’água a 100oC. O calor de fusão do gelo é 80cal/g, o calor de condensação do vapor d’água é 540cal/g e o calor específico da água (líquida) é 1,0cal/goC. Quando se restabelece o equilíbrio térmico, a massa de água (líquida) contida no calorímetro é','{"A": "210g.", "B": "240g.", "C": "270g.", "D": "300g.", "E": "330g."}'::jsonb,'C',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',45,'Física',null,'O gráfico mostra como varia a força de repulsão entre duas esferas puntiformes, idênticas e igualmente carregadas, em função da distância entre elas. Considerando a constante eletrostática do vácuo como ko = 9.109 N.m2/C2, a intensidade da força de repulsão F entre as esferas, quando estiverem afastadas em 2 metros, é de','{"A": "12 N.", "B": "24 N.", "C": "26 N.", "D": "48 N.", "E": "64 N."}'::jsonb,'B',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',46,'Química',null,'Na tentativa de promover a separação de componentes de uma mistura heterogênea, um técnico a deixou em repouso, observando a sedimentação do componente sólido de maior densidade. Após um longo tempo, foi possível verter o componente líquido, sobrenadante, para outro frasco, separando-o do componente sólido, depositado ao fundo. A técnica de separação adotada é chamada','{"A": "separação magnética.", "B": "destilação simples.", "C": "tamisação.", "D": "filtração simples.", "E": "decantação."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',47,'Química',null,'O benzeno é uma substância química que se apresenta como líquido incolor em temperatura ambiente e pressão atmosférica (25oC e 1atm, respectivamente). Trata-se de uma substância altamente tóxica, apesar de seu aroma doce e agradável. Seus vapores, se inalados, causam dor de cabeça, inconsciência e, em período prolongado de exposição, leucopenia. É imiscível em água e possui ponto de ebulição igual a 80oC. A esse respeito, analise as afirmativas a seguir. I. Em pressão atmosférica, o ponto de fusão do benzeno é maior que 25oC. II. Em temperatura superior a 80oC e pressão atmosférica, o benzeno estará no estado gasoso. III. A evaporação de benzeno ocorre apenas em temperatura acima de 80oC, logo não há risco de inalação de vapores em temperatura ambiente. Está correto o que se afirma em','{"A": "I, apenas.", "B": "II, apenas.", "C": "I e II, apenas.", "D": "I e III, apenas.", "E": "I, II e III."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',48,'Química',null,'O escândio é um elemento químico de símbolo Sc que apresenta número atômico igual a 21. É sólido a 25oC, metálico, macio, de cor branco-prateada. A configuração eletrônica do escândio, no estado fundamental, é:','{"A": "K: 8; L: 8; M: 5.", "B": "K: 2; L: 8; M: 11.", "C": "K: 2; L: 2; M: 15; N: 2.", "D": "K: 2; L: 8; M: 8; N: 3.", "E": "K: 2; L: 8; M: 9; N: 2."}'::jsonb,'E',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',49,'Química',null,'O carbono possui 3 isótopos naturais: 6C12, 6C13 e 6C14. As abundâncias dos isótopos 6C12 e 6C13 são, respectivamente, 98,9% e 1,1%, restando apenas traços do 6C14. Sobre os átomos 6C12, 6C13 e 6C14, é correto afirmar que eles possuem','{"A": "números de prótons diferentes.", "B": "números de nêutrons diferentes.", "C": "números de elétrons diferentes.", "D": "números atômicos diferentes.", "E": "números de camadas eletrônicas diferentes."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',50,'Química',null,'O ácido oxálico está presente em diversos alimentos, principalmente nas folhas de vegetais, como a acelga suíça, a beterraba, o espinafre e o ruibarbo. Também é encontrado no amendoim e no cacau. Trata-se um ácido dicarboxílico, de fórmula molecular C2H2O4. Considere as massas atômicas C: 12g mol–1, H: 1g mol–1 e O: 16gmol–1. A massa molecular do ácido oxálico, em g mol–1, é','{"A": "29", "B": "45", "C": "58", "D": "90", "E": "114"}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',51,'Química',null,'O efeito fotoelétrico é um fenômeno de origem quântica que consiste na emissão de elétrons por algum material que é iluminado por radiações eletromagnéticas de frequências específicas. Os elétrons emitidos por esses materiais são chamados de fotoelétrons. Considere os átomos sódio (Na), potássio (K), ferro (Fe), césio (Cs) e iodo (I). Nesse conjunto, o átomo que necessita de radiação eletromagnética de menor frequência para a emissão de fotoelétrons é','{"A": "Na", "B": "K", "C": "Fe", "D": "Cs", "E": "I"}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',52,'Química',null,'Avogadro (1776-1856) estimou que o diâmetro de um átomo é em torno de 10-10 m. Um século mais tarde, Ernest Rutherford (1871-1937) estimou que os núcleos atômicos possuem diâmetro de cerca de 10–14m. A diferença entre os diâmetros foi explicada pela presença de prótons e nêutrons no núcleo muito denso e pela disposição de elétrons em camadas na eletrosfera, num modelo atômico planetário. A esse respeito, analise as afirmativas a seguir. I. O raio atômico do estrôncio é igual ao raio atômico da prata, pois ambos átomos possuem o mesmo número de camadas eletrônicas. II. O raio atômico do cálcio é maior do que o raio atômico do bário, pois o cálcio apresenta maior número de camadas eletrônicas. III. O raio atômico do potássio é maior do que o raio atômico do zinco, pois o potássio tem menor carga nuclear. Está correto o que se afirma em','{"A": "I, apenas.", "B": "II, apenas.", "C": "III, apenas.", "D": "I e III, apenas.", "E": "II e III, apenas."}'::jsonb,'C',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',53,'Química',null,'Cloreto de lítio é um sal higroscópico altamente solúvel em água. Sua solubilidade em solventes orgânicos como metanol e acetona é maior do que a solubilidade de cloreto de sódio ou cloreto de potássio. É preparado pela reação de carbonato de lítio com ácido clorídrico e usado na produção de lítio metálico através de eletrólise ígnea. Dados: valores de eletronegatividade de Pauling: Li = 1,0; Cl = 3,0. Assinale a opção que apresenta o tipo de ligação química que ocorre no cloreto de lítio.','{"A": "Iônica.", "B": "Covalente polar.", "C": "Covalente apolar.", "D": "Coordenada.", "E": "Metálica."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',54,'Química',null,'A regra do octeto estabelece que os átomos devem possuir oito elétrons em sua camada de valência de modo a atingir a estabilidade. Assim, ligações químicas se estabelecem, por transferência ou compartilhamento de elétrons, de forma que cada átomo possa ficar com oito elétrons na camada de valência, semelhante a um gás nobre. Embora muito útil para a determinação da fórmula de compostos químicos, essa regra apresenta inúmeras exceções e ligações químicas em que se observa a expansão ou a contração do octeto. Assinale a opção na qual ambos os compostos representam exceções à regra do octeto.','{"A": "BF3 e KCl", "B": "BeCl2 e NO", "C": "SF6 e CaCl2", "D": "KBr e NaF", "E": "Cl2 e SO3"}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',55,'Química',null,'O óxido de silício, SiO2, é a principal matéria prima do vidro. Além dele, outros óxidos são misturados com finalidades diversas. Por exemplo, o óxido de sódio (Na2O) e o óxido de potássio (K2O) são responsáveis pelo abaixamento do ponto de fusão da mistura; o óxido de cálcio (CaO) é introduzido com a finalidade de dificultar a cristalização da sílica trazendo a transparência ao produto final; o óxido de alumínio (Al2O3) agrega resistência a choques mecânicos; e o óxido de magnésio (MgO) aumenta a capacidade de suportar mudanças bruscas de temperatura. Assinale a opção que contém apenas óxidos básicos.','{"A": "Na2O e MgO.", "B": "Al2O3 e Na2O.", "C": "SiO2 e Al2O3.", "D": "K2O e Al2O3.", "E": "SiO2 e CaO."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',56,'Química',null,'O ácido fosfórico (H3PO4) é usado na indústria de alimentos como acidulante de bebidas. No Brasil, esse ácido é empregado nas formulações de refrigerantes, diminuindo o valor do pH, regulando a doçura e realçando o paladar. Além disso, o ácido fosfórico atua como conservante do produto. Ele pode ser obtido a partir do tratamento da apatita (um mineral que contém fosfato de cálcio) com ácido sulfúrico (H2SO4), formando também sulfato de cálcio. As fórmulas dos compostos fosfato de cálcio e sulfato de cálcio são, respectivamente,','{"A": "Ca3PO4 e Ca2SO4.", "B": "Ca3(PO4)2 e CaSO4.", "C": "Ca(PO4)2 e CaSO4.", "D": "Ca(PO4)3 e Ca(SO4)3.", "E": "Ca2(PO4)3 e CaSO4."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',57,'Química',null,'Óxidos ácidos presentes na atmosfera, em contato com a chuva, dissolvem-se e causam a diminuição do pH. A chuva, então contaminada por tais óxidos, é comumente chamada chuva ácida. Assinale a opção que apresenta um óxido que pode contribuir para a formação de chuvas ácidas.','{"A": "NH3", "B": "BaO", "C": "SO3", "D": "CH4", "E": "CO"}'::jsonb,'C',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',58,'Química',null,'Considere a reação química entre permanganato de potássio (KMnO4) e sulfato ferroso (FeSO4) em meio ácido: a KMnO4 + b FeSO4 + c H2SO4 → d Fe2(SO4)3 + e K2SO4 + f MnSO4 + + g H2O A soma dos coeficientes estequiométricos (a + b + c + d + e + f + g) que tornam a equação balanceada é igual a','{"A": "21.", "B": "26.", "C": "30.", "D": "36.", "E": "42."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',59,'Química',null,'O processo industrial de síntese de ureia ((NH2)2CO) passa por duas etapas principais: 2NH3 + CO2  NH2C(O)ONH4 NH2C(O)ONH4  (NH2)2CO + H2O As etapas são, respectivamente, classificadas como reações de','{"A": "síntese e dupla troca.", "B": "síntese e síntese.", "C": "deslocamento e decomposição.", "D": "síntese e decomposição.", "E": "deslocamento e dupla troca."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',60,'Química',null,'O hidrogênio (H2) é considerado o combustível do futuro, porque sua queima gera grande quantidade de energia e o resíduo de combustão é água. A equação química que representa essa combustão é: 2 H2(g) + O2(g) → 2 H2O(g) Nessa reação, o hidrogênio reage com o oxigênio em proporção 1:8 (em massa). A esse respeito, analise as afirmativas a seguir. I. A combustão completa de 5g de hidrogênio requer 40g de oxigênio. II. A mistura de 4g de hidrogênio com 16g de oxigênio deverá gerar 20g de água. III. A combustão de 2g de hidrogênio gera 2g de água. Está correto o que se afirma em','{"A": "I, apenas.", "B": "II, apenas.", "C": "III, apenas.", "D": "I e II, apenas.", "E": "I, II e III."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',61,'Biologia',null,'O Corpo de Bombeiros atua, com frequência, em ocorrências que envolvem a contenção e captura de animais silvestres, especialmente serpentes. A chegada do verão, as construções próximas à região de mata e a destruição do habitat natural são fatores que ajudam a explicar, segundo especialistas, as aparições desses animais em áreas urbanas. As serpentes são répteis classificados no grupo dos lepidosauros e apresentam características como','{"A": "a ectotermia, a respiração cutânea e o coração dividido em 3 cavidades.", "B": "a respiração pulmonar, a viviparidade e a fecundação externa.", "C": "a pele queratinizada, a ectotermia e a circulação dupla e fechada.", "D": "a fecundação externa, a pecilotermia e a pele queratinizada, sem glândulas mucosas.", "E": "o ovo amniótico, a homeotermia e o coração com quatro cavidades."}'::jsonb,'C',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',62,'Biologia',null,'A taxonomia é o ramo da biologia que nomeia e classifica os seres vivos, ordenando-os em grupos de acordo com o maior ou o menor grau de características compartilhadas entre eles. Atualmente, as unidades de classificação dos seres vivos mais abrangentes são os reinos e os domínios. Com relação a essas unidades, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) No sistema de classificação em cinco reinos, apenas um deles, o reino Protista, agrupa todos os organismos procariontes. ( ) Os domínios são categorias mais abrangentes do que os reinos. Um único domínio, Eukarya, inclui organismos de quatro reinos – Protista, Fungi, Plantae e Animalia. ( ) Nos domínios Bacteria e Archaea podem ser encontrados organismos autótrofos ou heterótrofos. Já o domínio Eukarya engloba apenas organismos heterótrofos. As afirmativas são, na ordem apresentada, respectivamente,','{"A": "F, V e F.", "B": "F, V e V.", "C": "V, F e F.", "D": "V, V e F.", "E": "F, F e V."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',63,'Biologia',null,'Os organismos multicelulares são constituídos por diversos tipos de células. O esquema a seguir apresenta neurônios que exemplificam o ajuste entre forma e função que surge ao longo da evolução. A habilidade dos neurônios em receber e transmitir informações baseia-se em sua organização celular altamente especializada. No esquema acima, a especialização que permite a maior velocidade na condução do impulso nervoso em neurônios de vertebrados está indicada pelo número','{"A": "1.", "B": "2.", "C": "3.", "D": "4.", "E": "5."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',64,'Biologia',null,'No portal do CBMERJ são encontradas diversas cartilhas para consulta, entre elas, a intitulada “Varíola dos macacos, o que você precisa saber”. Essa cartilha contém informações sobre os sintomas da doença, seu agente etiológico e as formas de transmissão, tratamento e prevenção. Com relação à varíola dos macacos e a seu agente etiológico, analise as afirmativas a seguir. I. A doença é causada por vírus, organismos cuja ausência de organização celular e metabolismo próprio os torna parasitas intracelulares obrigatórios. II. Não há tratamento específico e os sintomas desaparecem espontaneamente entre duas e três semanas, graças à imunidade ativa, na qual o organismo da pessoa infectada gera anticorpos que combatem a doença. III. Assim como as arboviroses dengue e febre amarela, o agente etiológico da varíola dos macacos é transmitido por meio da picada da fêmea de mosquitos. Está correto o que se afirma em','{"A": "I, apenas.", "B": "I e II, apenas.", "C": "I e III, apenas.", "D": "II e III, apenas.", "E": "I, II e III."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',65,'Biologia',null,'No interior das células, os processos de fotossíntese e respiração celular realizam as transformações de energia necessárias à manutenção da vida. A figura a seguir mostra esses processos, de forma simplificada. Sobre as organelas e os processos representados, assinale a afirmativa correta.','{"A": "A fotossíntese ocorre na organela I e é responsável pela transformação da energia química contida nas moléculas de glicose em energia química das moléculas de ATP.", "B": "A organela assinalada por II é o cloroplasto e nela ocorre a transformação da energia luminosa em energia química, que fica armazenada em moléculas de glicose.", "C": "A transformação das moléculas de ATP em moléculas de glicose ocorre na organela I, que representa o cloroplasto das células vegetais.", "D": "O número II indica uma mitocôndria, organela responsável pelo aproveitamento da energia contida em moléculas de gás carbônico e água absorvidas pelos organismos.", "E": "As organelas I e II podem ser encontradas em vegetais, porém a organela I está ativa apenas durante a noite, enquanto a organela II está ativa durante o dia, em presença de luz."}'::jsonb,'B',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',66,'Biologia',null,'Se você nunca sofreu uma queimadura por água-viva, certamente conhece alguém que já passou por isso. "Até abril é quando ocorre a maior quantidade de queimaduras deste tipo na orla das praias”, afirma uma capitã do GBMar (Grupamento de Bombeiros Marítimo), unidade operacional do Corpo de Bombeiros especializada em atividades aquáticas. (Adaptado de Revista Crescer, 28/01/2022) As águas-vivas apresentam em sua superfície corporal células urticantes com nematocistos em seu interior, responsáveis pelos acidentes mencionados acima. Esses animais pertencem ao filo','{"A": "Cnidaria, formado por animais triblásticos e com simetria bilateral.", "B": "Porifera, formado por animais diblásticos e com simetria bilateral.", "C": "Cnidaria, formado por animais diblásticos e com simetria radial.", "D": "Porifera, formado por animais triblásticos e com simetria radial.", "E": "Cnidaria, formado por animais diblásticos e com simetria bilateral."}'::jsonb,'C',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',67,'Biologia',null,'Analise o heredograma abaixo que mostra uma doença de herança autossômica representada pelos quadrados e círculos em branco. Com relação a essa doença, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A doença tem herança autossômica recessiva. ( ) A geração parental é, obrigatoriamente, heterozigota. ( ) Entre os filhos do casal representado no heredograma, os que não apresentam a doença têm 2/4 de chance de serem heterozigotos. As afirmativas são, na ordem apresentada, respectivamente,','{"A": "F, F e V.", "B": "V, F e V.", "C": "F, V e F.", "D": "V, V e F.", "E": "V, V e V."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',68,'Biologia',null,'Em 2020, um incêndio atingiu o Parque Nacional da Tijuca e se alastrou por uma área equivalente a trinta campos de futebol. A causa provável do incêndio foi a queda de balões e o combate ao fogo foi feito por brigadistas e voluntários do Parque, junto com equipes do Corpo de Bombeiros do Rio de Janeiro. Na Floresta da Tijuca, as angiospermas constituem a maioria das espécies de plantas. Este grupo vegetal é formado por plantas','{"A": "avasculares, com flores e sementes, mas sem frutos.", "B": "vasculares, com flores e sementes, mas sem frutos.", "C": "avasculares, com sementes, mas sem flores e frutos.", "D": "vasculares, com flores, frutos e sementes.", "E": "avasculares, com flores e frutos, mas sem sementes."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',69,'Biologia',null,'Certa vesícula, muito frequente no citoplasma de células com funções fagocitárias, é delimitada por membrana e contém enzimas capazes de digerir moléculas orgânicas em geral. Essa estrutura é o','{"A": "retículo endoplasmático rugoso.", "B": "peroxissomo.", "C": "complexo golgiense.", "D": "lisossomo.", "E": "vacúolo contrátil."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',70,'Biologia',null,'Observe o esquema que compara o esqueleto dos membros anteriores de humanos e aves. (Adaptado de AMABIS e MARTHO, Biologia Moderna, vol. 3 São Paulo: Moderna, 2016) Os ossos dos braços humanos são estruturas','{"A": "análogas às asas das aves e a diferença de funções entre elas se deve à evolução divergente que sofreram.", "B": "homólogas às asas das aves e a diferença de funções entre elas se deve à evolução divergente que sofreram.", "C": "análogas às asas das aves e a diferença de funções entre elas se deve à evolução convergente que sofreram.", "D": "homólogas às asas das aves e a diferença de funções entre elas se deve à evolução convergente que sofreram.", "E": "vestigiais em relação às asas das aves e a diferença de funções entre elas se deve à evolução convergente que sofreram."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',71,'Geografia',null,'Leia o fragmento a seguir: “As chuvas encontram-se desigualmente distribuídas no globo. No sentido das longitudes, observa-se uma oposição entre as costas ocidentais e orientais dos continentes. Nas baixas latitudes, as primeiras são habitualmente pouco chuvosas, ocorrendo o inverso nas orientais, ao passo que nas latitudes altas e médias verifica- se o oposto. Isto se repete simetricamente em todos os continentes, aparecendo de forma mais nítida no hemisfério sul.” (Adaptado de: Ross, Jurandyr (org.). Geografia do Brasil, 2005: 95) O padrão de distribuição das chuvas descrito no fragmento acima se deve à ação','{"A": "dos ventos alísios.", "B": "das frentes polares.", "C": "das correntes marítimas.", "D": "dos ciclones subtropicais.", "E": "da zona de convergência intertropical."}'::jsonb,'C',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',72,'Geografia',null,'Bem público por excelência, a água se transformou em um bem mercantil em virtude do aumento da demanda e dos custos cada vez mais elevados de captação, distribuição e tratamento, sobretudo a partir de meados do século XX. Sobre o uso de água doce no mundo, analise as afirmações a seguir. I. A maior parte das águas residuais retorna ao ambiente após tratamento adequado. II. A Ásia é o continente com maior participação das terras irrigadas no total de terras agrícolas. III. O setor industrial é responsável pela maior parte do consumo de água doce, quando comparado aos setores doméstico e agrícola. Está correto o que se afirma em','{"A": "I, apenas.", "B": "II, apenas.", "C": "III, apenas.", "D": "I e III, apenas.", "E": "I, II e III."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',73,'Geografia',null,'Como parte do ciclo global de carbono, a cobertura florestal é um valioso indicador da saúde climática. De acordo com a Organização das Nações Unidas para a Alimentação e a Agricultura (FAO), a cobertura florestal mundial abrange mais de quatro milhões de hectares, cerca de 30% da superfície total das terras emersas. Considerando a distribuição atual da cobertura florestal e suas alterações em escala mundial nas primeiras décadas do século XX, assinale V para a afirmativa verdadeira e F para a falsa. ( ) O Brasil está entre os cinco países com maior superfície florestal do mundo. ( ) Nas duas primeiras décadas do século XX houve um aumento da superfície florestal em escala mundial. ( ) Entre as zonas climáticas, a zona temperada é a que possui o maior percentual da cobertura florestal do planeta. As afirmativas são, respectivamente,','{"A": "F, V e F.", "B": "V, V e V.", "C": "V, F e V.", "D": "V, F e F.", "E": "F, F e V."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',74,'Geografia',null,'A queda do muro de Berlim, em 1989, marcou simbolicamente o fim do período da Guerra fria e o ocaso da ordem bipolar que articulou o mundo no pós-guerra. Sobre a “nova ordem mundial”, analise as afirmações a seguir. I. No plano militar, a China desempenha um papel de potência regional. II. A presença de outros polos de poder geopolítico limita a hegemonia norte-americana. III. As rendas das exportações de combustíveis fósseis constituem um alicerce para o projeto russo de restauração de sua influência mundial. Está correto o que se afirma em','{"A": "I, apenas.", "B": "II, apenas.", "C": "III, apenas.", "D": "I e III, apenas.", "E": "I, II e III."}'::jsonb,'E',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',75,'Geografia',null,'A população mundial atual é mais de três vezes maior do que aquela registrada em meados do século XX e, de acordo com as previsões da Organização das Nações Unidas (ONU), alcança a cifra de oito bilhões de pessoas ainda em 2022. Entre as regiões do globo, aquela que apresenta, na atualidade, as maiores taxas de crescimento populacional e a menor participação de pessoas com mais de 65 anos na população total é a região da','{"A": "África subsaariana.", "B": "América Latina e Caribe.", "C": "Europa e América do Norte.", "D": "Ásia Ocidental e Sul-ocidental.", "E": "África Setentrional e Ásia Ocidental."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',76,'Geografia',null,'Leia o fragmento a seguir: “A cisão entre o litoral e o interior, entre o mar e o sertão, caracterizou, desde os primeiros tempos, a formação territorial da América Portuguesa. Essa divisão perseverou durante séculos e imprimiu sua marca à cultura brasileira.” (adaptado de: Magnoli, Demétrio. Geografia para o ensino médio. São Paulo: Atual, 2008: 214) Considerando o processo de ocupação, no período colonial, da área que corresponde à atual macrorregião Nordeste, analise as afirmativas a seguir: I. No século XVI, as missões jesuíticas organizaram a coleta de drogas do Sertão na região do semiárido. II. No século XVII, a pecuária se deslocou rumo ao interior, nas direções dos rios Parnaíba e São Francisco. III. No século XVIII, a cafeicultura se expandiu nas manchas de terra roxa situadas na faixa litorânea. Está correto o que se afirma em','{"A": "I, apenas.", "B": "II, apenas.", "C": "III, apenas.", "D": "I e III, apenas.", "E": "I, II e III."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',77,'Geografia',null,'Segundo os dados do portal da Indústria (2019), o estado de São Paulo é responsável por cerca de 29% do Produto Interno Bruto industrial do Brasil e por cerca de 30% da força de trabalho industrial do país. Sobre o processo de industrialização do estado de São Paulo, analise as informações a seguir. I. A cidade de São Paulo se transformou no principal polo industrial do país na primeira metade do século XX. II. A indústria automobilística se manteve concentrada na capital do estado até a primeira década do século XXI. III. A descentralização industrial seguiu os eixos rodoviários que ligam a Grande São Paulo às cidades médias do interior. Está correto o que se afirma em','{"A": "I, apenas.", "B": "II, apenas.", "C": "III, apenas.", "D": "I e III, apenas.", "E": "I, II e III."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',78,'Geografia',null,'A partir da década de 1930, houve uma aceleração do processo de urbanização do território brasileiro. De acordo com os dados do Censo Demográfico, em 1970 a população urbana já era maior do que a população rural. Já no ano de 2000, cerca de 80% da população brasileira habitava o meio urbano. Entretanto, esse processo ocorreu de forma desigual no país. Considerando o processo de urbanização nas grandes regiões brasileiras, ao longo do século XX, assinale V para a afirmativa verdadeira e F para a falsa. ( ) Na região Norte, a população permaneceu predominantemente rural até o final do século XX. ( ) Na região Centro-Oeste, houve uma involução urbana com o avanço da moderna agricultura comercial, que impulsionou a migração para as áreas rurais. ( ) Na região Sudeste, a urbanização impulsionou o fluxo migratório proveniente do Nordeste, acelerando o crescimento dos grandes centro urbanos. As afirmativas são, respectivamente,','{"A": "F, V e F.", "B": "V, V e V.", "C": "V, F e V.", "D": "V, V e F.", "E": "F, F e V."}'::jsonb,'E',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',79,'Geografia',null,'A agricultura familiar apresenta dinâmica e características distintas da agricultura não familiar. Nela, a gestão da propriedade é compartilhada pela família e a atividade produtiva agropecuária é a principal fonte geradora de renda. Segundo o Censo Agropecuário de 2017, o valor da produção da agricultura familiar equivale a quase 25% de toda a produção agropecuária brasileira. Considerando o total de pessoas ocupadas no setor agropecuário, a macrorregião brasileira que apresenta o maior percentual na agricultura familiar é a região','{"A": "Sul.", "B": "Norte.", "C": "Sudeste.", "D": "Nordeste.", "E": "Centro-Oeste."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',80,'Geografia',null,'Entre os anos de 2000 e 2010, houve um aumento da participação das mulheres no mercado de trabalho brasileiro. Entretanto, observam-se diferenças significativas em relação aos homens, mas também entre alguns segmentos específicos das mulheres. Sobre a participação das mulheres no mercado de trabalho brasileiro, em 2010, assinale V para a afirmativa verdadeira e F para a falsa. ( ) A taxa de atividade das mulheres de mais de 60 anos era maior do que a dos homens no mesmo grupo de idade. ( ) A taxa de atividade das mulheres era maior em áreas urbanas do que em áreas rurais. ( ) A taxa de atividade das mulheres na região Nordeste era a mais alta entre as grandes regiões do país. As afirmativas são, respectivamente,','{"A": "F, V e F.", "B": "V, V e V.", "C": "V, F e V.", "D": "V, V e F.", "E": "F, F e V."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',81,'História',null,'Observe os oito círculos do sistema mundial (século XIII): eles representam os principais circuitos comerciais da Eurásia e da África. Fonte: J.L. Abu-Lughod, Before European Hegemony, 1989, p. 34. Com base no mapa, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Os circuitos 2 e 3 mostram que o Mar Mediterrâneo era dominado pelas cidades italianas de Veneza e Gênova, as quais, desde o século XI, apoiaram as Cruzadas para obter mercadorias orientais de luxo que chegavam até o Império Bizantino e Oriente Próximo. ( ) O circuito 3 mostra o eixo terrestre da rota da seda, que conectava o império Yuan chinês a Antioquia, na Síria medieval, constituindo uma via comercial para seda, papel, chá e cerâmica para o Oeste e vidro e produtos metalúrgicos para o Oriente, entre outros. ( ) Os circuitos 3 e 4 mostram a vitória do Islã sobre os mongóis, no século XIII, e a expansão do califado de Bagdá como centro propulsor do comércio e do expansionismo dos Omíada no Oriente Médio. Assinale a opção que indica a sequência correta, de cima para baixo.','{"A": "V, V e F.", "B": "F, F e V.", "C": "F, V e V.", "D": "V, F e F.", "E": "V, V e V."}'::jsonb,'A',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',82,'História',null,'Os aspectos assinalados a seguir são traços comuns à civilização do Renascimento e à do Iluminismo, à exceção de um. Assinale-o.','{"A": "Teocentrismo.", "B": "Visão laica da vida.", "C": "Exaltação da razão humana.", "D": "Desenvolvimento de ideia de religião universal.", "E": "Concepção de homem como artífice de si mesmo."}'::jsonb,'A',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',83,'História',null,'A democracia é uma construção coletiva com raízes históricas que remontam à Antiguidade Clássica. Para a civilização greco-romana, a democracia','{"A": "contrapunha-se à oligarquia, sistema em que os proprietários de terra contratavam guerreiros e mercenários para restringir o direito de fala em praça pública, como em Esparta.", "B": "realizava-se pelo autogoverno dos cidadãos livres que, independente de riqueza e status, eram credenciados para participar diretamente das decisões coletivas, como em Atenas, no tempo de Péricles.", "C": "baseava-se em voto individual, e com o mesmo peso, na deliberação coletiva, o que favorecia a ascensão política de uma maioria de governantes proveniente da plebe, em Roma, e de cidadãos não proprietários, em Atenas.", "D": "fundamentava-se na ideia de liberdade política, em contraposição ao modelo imperial persa, que permitia certo grau de participação popular, mas vinculada a critérios econômicos e censitários.", "E": "designava uma forma de governo popular e representativa, em que a classe política escolhida defende os interesses do povo, diferentemente de monarquias, como a romana e a espartana, por exemplo."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',84,'História',null,'“Nem todo movimento reacionário é fascista. Nem toda repressão – por mais feroz que seja – exercida em nome da conservação de privilégios de classe ou casta é fascista. Por outro lado, o conceito de fascismo não se deixa reduzir aos de ditadura ou de autoritarismo”. Adaptado de KONDER, Leandro. Introdução ao fascismo. Rio de Janeiro: Edições do Graal, 1977. p. 4. A partir do trecho, pode-se afirmar que o fascismo é','{"A": "uma ideologia pautada na divisão e autonomia dos poderes, formulada por um líder nacionalista, capaz de angariar o apoio das massas populares.", "B": "um sistema de governo em que o cidadão participa da vida política ao se submeter aos interesses do Estado, considerado o órgão que representa a coletividade.", "C": "uma forma de comportamento político preocupado com a humilhação imposta a uma comunidade e organizada por um partido militante nacionalista, de base popular, que repudia as liberdades democráticas.", "D": "uma doutrina política baseada no princípio da ação popular, apoiada por nacionalistas de esquerda, em confronto com os interesses de setores conservadores, dos quais buscam retirar o monopólio dos meios de coerção.", "E": "um fenômeno cujo êxito resulta da capacidade de propor mudanças sociais e projetos de engrandecimento econômico- militar que são negociados em parlamento e apoiados por coligações partidárias majoritárias."}'::jsonb,'C',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',85,'História',null,'Observe o mapa a seguir. As fronteiras do território que hoje chamamos “Brasil” delineadas no mapa foram estabelecidas pelo','{"A": "Tratado de Tordesilhas (1494).", "B": "Tratado de Lisboa (1681).", "C": "Tratado de Utrecht entre Portugal e França (1713).", "D": "Tratado de Utrecht entre Portugal e Espanha (1715).", "E": "Tratado de Madrid (1750)."}'::jsonb,'E',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',86,'História',null,'“No processo de conquista e colonização da América, os portugueses dependeram fundamentalmente dos povos indígenas. Os diferentes grupos etnolinguísticos aqui encontrados, tais como os Tamoio, Tupiniquim, Aimoré, e Goitacaz, entre outros, foram todos chamados índios pelos europeus. Na condição de aliados ou inimigos, eles desempenharam importantes e variados papéis na nova colônia que, então, se construía”. Maria Regina Celestino de Almeida, “Povos Indígenas no Brasil”, in http://bndigital.bn.gov.br A respeito das relações entre europeus e indígenas, durante o período de colonização da América Portuguesa, assinale a afirmativa correta.','{"A": "A chegada dos europeus na América gerou uma catástrofe demográfica, fruto da incapacidade de adaptação de portugueses, holandeses e ingleses à vida nos trópicos.", "B": "Os Tapuia habitavam o litoral e, por isso, os portugueses tiveram um contato mais prolongado com eles, o que permitiu que fossem mais bem conhecidos pelos europeus.", "C": "O vocábulo Tupi significava bárbaro para os ameríndios e foi usado para designar todos os grupos não Tapuia com os quais os colonizadores se deparavam.", "D": "A grande variedade de povos com línguas e culturas diversas foi reduzida a dois grandes grupos, Tupi e Tapuia, pelos cronistas, missionários e agentes europeu da colonização.", "E": "A principal estratégia da Coroa para submeter os ameríndios às leis do império português foi a subvenção de aldeamentos missionários franciscanos, sobretudo no sertão vicentino."}'::jsonb,'D',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',87,'História',null,'A cidadania não se restringe ao voto. A Constituição de 1988 previu diversas formas de exercer a cidadania além da consulta eleitoral, como, por exemplo, atuar em órgãos considerados importantes instâncias de participação social, garantidos pela Constituição nas áreas da saúde, educação e assistência social. Estes órgãos são deliberativos e contam com participação de organizações da sociedade civil e representantes do Estado em proporções iguais. Suas reuniões são abertas à população e tratam de diferentes temas como juventude, direitos da mulher, mobilidade urbana, meio ambiente, entre tantos outros. O texto se refere à participação em','{"A": "ouvidorias públicas", "B": "conselhos municipais.", "C": "orçamento participativo.", "D": "audiências públicas da cidade.", "E": "sessões legislativas na Câmara dos Vereadores."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',88,'História',null,'Com base no gráfico, analise as afirmativas a seguir sobre a geopolítica do petróleo, desde os anos 1970. I. Em 1973, o petróleo árabe foi usado como arma contra o mundo ocidental, principalmente contra os Estados Unidos e os países europeus que apoiaram Israel na Guerra do Yom Kippur, contra Egito e Síria. II. Em 1979, a paralisação da produção petrolífera do Irã, em função da Revolução Islâmica liderada pelo aiatolá Khomeini, provocou uma crise que fez explodir o preço médio do barril. III. Em 2011, as guerras na Líbia e na Síria contribuíram para altas expressivas no preço do barril, sobretudo em função da intensidade da Primavera Árabe na Arábia Saudita, o maior produtor de petróleo. Está correto o que se afirma em','{"A": "I, apenas.", "B": "I e II, apenas.", "C": "I e III, apenas.", "D": "II e III, apenas.", "E": "I, II e III."}'::jsonb,'B',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',89,'História',null,'Na noite de 16 de dezembro de 1773, um grupo de homens disfarçados de índios, autodenominados Filhos da Liberdade, embarcou em três navios e despejou o carregamento de chá no porto de Boston. Nathaniel Currier. Destruição do chá no porto de Boston, 1846 Esse episódio ficou conhecido como a “Festa do chá em Boston” e teve como objetivo principal','{"A": "atacar a Companhia Holandesa das Índias Orientais (VOC), responsável pelo contrabando de chá nas colônias americanas e pelos prejuízos aos comerciantes de chá inglês.", "B": "protestar contra a Lei do Chá, considerada abusiva pois o debate sobre o tributo havia ocorrido no Parlamento inglês, no qual os colonos não tinham direito de representação.", "C": "punir as atividades de comerciantes holandeses e norte- americanos que contrabandeavam chá holandês, eliminando a remessa do produto no porto de Boston.", "D": "defender a liberdade de comércio no Atlântico Norte, sobretudo em função da repressão indireta ao comércio triangular, reativada pela Lei do Chá.", "E": "lutar por um programa de independência americana, representado por colonos que se consideravam os habitantes originais da América, contra ingleses e holandeses."}'::jsonb,'B',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',90,'História',null,'A capa da Revista Careta de 1925 divulgou uma charge na qual, no cume de um monte havia uma cadeira dourada com a inscrição “Presidência da República”, ladeada por dois personagens em cujos chapéus havia a inscrição “São Paulo” e “Minas”. Ao pé do monte, um conjunto de outros personagens (Rio Grande do Sul, Santa Catarina, Paraná e Bahia, entre outros) tentava escalar o cume. Fonte: Alfredo Storni (Storni). Revista Careta, ano XVIII, número 897, 29 de agosto de 1925, capa. A charge representa um mecanismo político próprio da República Velha conhecido como','{"A": "coronelismo, ao caracterizar a presença de militares no governo brasileiro.", "B": "clientelismo, pois enfatiza a dificuldade de os homens do campo participar da vida política pelas eleições.", "C": "política do café com leite, ao mostrar a alternância de candidatos paulistas e mineiros na presidência da república.", "D": "patrimonialismo, uma vez que representa o poder político nas mãos de grandes proprietários.", "E": "federalismo, ao mostrar a disputa dos estados por maior autonomia em relação ao poder central."}'::jsonb,'C',true,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Corpo de Bombeiros Militar do Estado do Rio de Janeiro','Cadete BM – Curso de Formação de Oficiais',2022,'2022-11-27','Tipo 1',91,'Língua Inglesa','Língua Estrangeira - Inglês Read the text and answer the five questions that follow it. The exciting technologies revolutionizing firefighting in 2022 One of the most important tools for a firefighter in the field is the ability to communicate with other members of the crew, officers, and decision-makers. Communication can be the difference between being able to ask for – and receive – help, or being alone as fires move, shift, and change. Communication can be the difference between having the latest intelligence and knowledge about what is going on, or being in the dark. Communication is also the difference between having a coordinated, collaborative effort, or having a number of individuals operating independently – which is the least effective way to fight a fire. While cellular networks have expanded and improved tremendously – especially in the age of 5G – there are still areas of our country where cellular connectivity and other terrestrial mobile networks aren’t available. There are also some situations where the communications equipment that power terrestrial networks can be damaged in fires, and leave firefighters without connectivity. This is why mobile mesh networking will be a widely adopted technology for firefighters and hotshot crews in 2022. Mobile mesh networking can enable the use of communications and situational awareness tools – such as ATAK – off the grid in places where other terrestrial networks don’t exist. This means that firefighters will be able to share information and see each other’s locations even in isolated, remote locations. They can also be used to spread connectivity over a wide geographic area and to each individual without a single, centralized piece of equipment that can be compromised and fail. This means they can deliver resilient and redundant communications that is always available to the firefighter. Finally, mobile mesh networking can be a low-cost alternative to connecting IoT devices. Instead of each individual sensor requiring its own expensive cellular connection – or incredibly pricey satellite connection – mobile mesh can be used to connect IoT devices over a wide geographic area with no recurring cost. This can help accelerate fire-focused IoT programs, and enable the government to extend them to more areas at a lower cost to the taxpayer. Enabling resilient, reliable communications and situational awareness alone is enough to make mobile mesh networking a game-changer for firefighting. But its ability to inexpensively connect IoT devices and sensors that can make firefighting more proactive and less dangerous make mobile mesh technologies essential in 2022. Adapted from https://thelastmile.gotennapro.com/the-exciting-technologies- revolutionizing-firefighting-in-2022/','Based on the text, mark the statements below as true (T) or false (F). ( ) The best way to fight fire is to do it in a single-handed way. ( ) Mesh networking can make firefighting a safer job. ( ) 5G connectivity is available all over the country. The statements are, respectively,','{"A": "F – F – T.", "B": "T – F – T.", "C": "F – T – F.", "D": "T – F – F.", "E": "T – T – F."}'::jsonb,'C',false,false,'RJ','Bombeiros','https://conhecimento.fgv.br/sites/default/files/concursos/cadete_bm_do_1o_ano_do_curso_de_formacao_de_oficiaiscnm001_tipo_1_8461654891.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cbmerj2022_gabarito_definitivo_1.pdf','disciplina atribuída pela ordem do caderno'),
